// The water's procedural textures as ONE DataArrayTexture (layer 0 = foam, 1 = noise, 2 = caustic net). The data is
// generated by texbake.ts in the bake worker (bake.worker.ts).
import * as THREE from "three";
import { flag } from "../../flags";
import type { Scope } from "../../engine/res/scope";
import { releaseAfterUpload } from "../../engine/texture-release";

/** layer 0 = foam, layer 1 = noise, layer 2 = caustic net (one sampler unit for all) */
export interface WaterTextures { array: THREE.DataArrayTexture; size: number; fill(data: Uint8Array): void }

export function makeWaterTextures(size: number, scope: Scope, rebuildTex: () => Promise<Record<string, unknown>>): WaterTextures {
  const t = scope.texture("tex.world", new THREE.DataArrayTexture(new Uint8Array(12).fill(128), 1, 1, 3));
  t.format = THREE.RGBAFormat; t.type = THREE.UnsignedByteType;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.minFilter = THREE.LinearMipmapLinearFilter; t.magFilter = THREE.LinearFilter;
  t.generateMipmaps = true; t.anisotropy = flag("waniso") || 4; t.colorSpace = THREE.NoColorSpace; t.needsUpdate = true;
  return {
    array: t, size,
    fill(data: Uint8Array) {
      t.image = { data, width: size, height: size, depth: 3 };
      releaseAfterUpload(t, async () => ({ data: (await rebuildTex()).data as Uint8Array, width: size, height: size, depth: 3 }));
      t.needsUpdate = true;
    },
  };
}
